@warp k -> isla_ceniza spawn=bay_w
@warp g -> villa_aliso spawn=shore
@warp M -> gruta_eclipse spawn=door
# D1 (contract 68): the islet's heat: only the bearer of the Medalla Brasa (the 7th badge) can go on to the mouth; the others are pushed back onto the bush's cell.
@script gruta_gate step if !badge_brasa
    say gr.gate.no
    hero_walk S 1
@end
